```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmName ?director ?directorName ?birthDate
WHERE {
  VALUES ?film { dbr:In_the_Beginning_There_Was_Underwear dbr:Une_famille_à_louer }

  # film name (prefer dbp:name, fallback to rdfs:label)
  OPTIONAL { ?film dbp:name ?filmName . }
  OPTIONAL { ?film rdfs:label ?filmLabel .
             FILTER (lang(?filmLabel) = "en") }
  BIND (COALESCE(?filmName, ?filmLabel) AS ?filmName)

  # director (prefer dbp:director, fallback to dbo:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?directorAlt . }
  BIND (COALESCE(?director, ?directorAlt) AS ?director)

  # director name (prefer dbp:name, fallback to rdfs:label)
  OPTIONAL { ?director dbp:name ?directorName . }
  OPTIONAL { ?director rdfs:label ?directorLabel .
             FILTER (lang(?directorLabel) = "en") }
  BIND (COALESCE(?directorName, ?directorLabel) AS ?directorName)

  # director birth date (prefer dbo:birthDate, fallback to dbp:birthDate)
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
  OPTIONAL { ?director dbp:birthDate ?birthDateAlt . }
  BIND (COALESCE(?birthDate, ?birthDateAlt) AS ?birthDate)
}
LIMIT 100
